{
  "findings": [
    {
      "check_id": "CKV_AWS_19",
      "title": "S3 bucket encryption is not explicitly configured",
      "resource": "aws_s3_bucket.data",
      "severity": "HIGH",
      "explanation": "The bucket does not declare server-side encryption, leaving the required encryption behavior unmanaged by this Terraform configuration."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "Without versioning, overwritten or deleted objects cannot be recovered from previous versions, increasing the impact of accidental or malicious deletion."
    },
    {
      "check_id": "CKV_AWS_53",
      "title": "Public ACL blocking is not configured",
      "resource": "aws_s3_bucket.data",
      "severity": "HIGH",
      "explanation": "The file does not prevent public ACLs from being applied to the bucket, which could expose stored data."
    },
    {
      "check_id": "CKV_AWS_54",
      "title": "Public bucket policies are not blocked",
      "resource": "aws_s3_bucket.data",
      "severity": "HIGH",
      "explanation": "The file does not block public bucket policies, allowing a future policy change to make the bucket publicly accessible."
    },
    {
      "check_id": "CKV_AWS_55",
      "title": "Public ACLs are not ignored",
      "resource": "aws_s3_bucket.data",
      "severity": "HIGH",
      "explanation": "The bucket is not configured to ignore public ACLs, so an ACL could grant unintended public access."
    },
    {
      "check_id": "CKV_AWS_56",
      "title": "Public bucket access is not restricted",
      "resource": "aws_s3_bucket.data",
      "severity": "HIGH",
      "explanation": "The bucket lacks an account-level access restriction at the bucket boundary, increasing the risk of exposure through public policies."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Destructive bucket deletion is enabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "Setting force_destroy to true allows Terraform to permanently delete the bucket and all object versions during destruction, bypassing the recovery benefit of versioning."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"data\" {\n  bucket        = \"${local.resource_prefix.value}-data\"\n  force_destroy = false\n\n  versioning {\n    enabled = true\n  }\n\n  server_side_encryption_configuration {\n    rule {\n      apply_server_side_encryption_by_default {\n        sse_algorithm = \"aws:kms\"\n      }\n\n      bucket_key_enabled = true\n    }\n  }\n\n  tags = merge({\n    Name        = \"${local.resource_prefix.value}-data\"\n    Environment = local.resource_prefix.value\n    }, {\n  })\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"data\" {\n  bucket = aws_s3_bucket.data.id\n\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n",
  "fix_summary": "Enabled KMS-backed server-side encryption, bucket keys, and versioning; disabled destructive forced deletion; and added all four S3 public-access-block protections."
}
